import{z as A,x as l,o as t,c as h,q as r,j as s,D as e,d as n,s as o,S as i,b as m}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"Hansen–Jagannathan 界","description":"","frontmatter":{"title":"Hansen–Jagannathan 界","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/hansen-jagannathan.md","filePath":"econ/hansen-jagannathan.md","lastUpdated":1791063341000}'),p={name:"econ/hansen-jagannathan.md"};function B(d,a,c,g,u,D){const E=l("Mermaid");return t(),h("div",null,[a[2]||(a[2]=r('<h1 id="hansen–jagannathan-界" tabindex="-1">Hansen–Jagannathan 界 <a class="header-anchor" href="#hansen–jagannathan-界" aria-label="Permalink to &quot;Hansen–Jagannathan 界&quot;">​</a></h1><div class="epigraph"><p>可交易收益的夏普比，给随机折现因子的波动率下了一道不依赖偏好函数形式的界。</p><footer>—— Hansen and Jagannathan, Implications of Security Market Data for Models of Dynamic Economies, Journal of Political Economy 1991</footer></div><p>定位：<a href="/econ/stochastic-discount-factor">上一课</a>。无套利已经给出 \\(m\\gt 0\\) 使 \\(p=\\mathrm{E}[m x]\\)，风险溢价是与 \\(m\\) 的协方差。SDF 课点过名字：可交易夏普比越高，定价核必须越波动——但没有把不等式写出。本课缺口就是这道会计界。不校准消费模型，不估计市场 beta。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(0=\\mathrm{E}[m R^e]\\) 对任意可交易超额收益成立。这是一阶矩约束，尚未说 \\(m\\) 必须「抖」多少。候选很多：几乎常数的 \\(m\\) 对应风险中性，解释不了高夏普；很抖的 \\(m\\) 什么都能定价，又没有拒绝力。Hansen 与 Jagannathan（1991）问：在只使用收益数据、不指定效用的前提下，\\(m\\) 的波动至少要多大。</p><p>缺口不是再证明存在性，而是从内积推出可检验的下界。界被违反，则该候选 \\(m\\)（例如某组偏好给出的边际替代率）不可能定价这些收益——无论你是否愿意再调一个自由参数去拟合均值。</p><p><span class="marginnote">夏普比 \\(\\mathrm{E}[R^e]/\\sigma(R^e)\\) 是可交易策略的均值–波动权衡。HJ 界说：定价核的变异系数不能低于该策略能达到的最大夏普。这是 Cauchy–Schwarz，不是估计。</span></p><p><span class="marginnote">数字实例：取 \\(R^f=1.02\\)，则 \\(\\mathrm{E}[m]=1/1.02\\approx 0.98\\)。若市场最大夏普是 0.5，HJ 界要求 \\(\\sigma(m)\\ge 0.5\\times 0.98\\approx 0.49\\)——定价核的年波动要接近其均值的一半。一个波动只有 0.01 的&quot;准常数&quot;核，差了约 50 倍。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>由 \\(0=\\mathrm{E}[m R^e]=\\mathrm{E}[m]\\mathrm{E}[R^e]+\\mathrm{Cov}(m,R^e)\\) 得 \\(\\mathrm{E}[R^e]=-\\mathrm{Cov}(m,R^e)/\\mathrm{E}[m]\\)。Cauchy–Schwarz 给出 \\(|\\mathrm{Cov}(m,R^e)|\\le\\sigma(m)\\sigma(R^e)\\)，于是</p> \\[\\frac{\\sigma(m)}{\\mathrm{E}[m]} \\ge \\frac{|\\mathrm{E}[R^e]|}{\\sigma(R^e)}. \\]<p>右边换成可行集合里的最大夏普。\\(\\mathrm{E}[m]\\) 由无风险（或零 beta）锚定：\\(\\mathrm{E}[m]=1/R^f\\)。因此观察到的夏普直接限制 \\(\\sigma(m)\\)。股票相对债券的历史夏普大约 0.3–0.5 量级，则 \\(m\\) 的年波动不能太小——这是后课股权溢价之谜的会计入口，本课先停在不等式。</p><p>更一般的 HJ 界允许把 \\(m\\) 投影到收益空间，画出 \\((\\mathrm{E}[m],\\sigma(m))\\) 平面上的可行区域。候选模型必须落在区域上方。区域只用价格与收益，不用消费。</p>',13)),(t(),s(i,null,{default:e(()=>[o(E,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20SDF%5B%220%20%3D%20E%5Bm%20Re%5D%22%5D%20--%3E%20CS%5B%22Cauchy-Schwarz%22%5D%0A%20%20CS%20--%3E%20BD%5B%22sigma(m)%2FE%5Bm%5D%20%3E%3D%20Sharpe%22%5D%0A%20%20BD%20--%3E%20FEAS%5B%22(E%5Bm%5D%2C%20sigma(m))%20%E5%8F%AF%E8%A1%8C%E5%9F%9F%22%5D%0A%20%20CAND%5B%22%E5%80%99%E9%80%89%20m%3A%20%E5%A6%82%20u'(c)%22%5D%20--%3E%20FEAS%0A%20%20FEAS%20--%3E%20REJ%5B%22%E8%90%BD%E5%9C%A8%E5%9F%9F%E4%B8%8B%3A%20%E4%B8%8D%E8%83%BD%E5%AE%9A%E4%BB%B7%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=m("p",null,[n("与 "),m("a",{href:"/econ/emh"},"EMH"),n(" 的接法：经 \\(m\\) 调整后无利润，是有效的核语言；HJ 说的是这个 \\(m\\) 不能太平。有效可以成立而候选 \\(m\\) 仍被界拒绝——拒绝的是偏好或因子，不是信息分层。")],-1)),a[4]||(a[4]=m("h2",{id:"机制",tabindex:"-1"},[n("机制 "),m("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=m("p",null,"机制是线性定价的几何。所有可交易超额收益张成一个向量空间；\\(m\\) 必须与该空间正交（内积为零）。正交条件能约束的是 \\(m\\) 在该空间上的投影，投影的范数至少等于最大夏普。偏好给出的 \\(m\\) 若几乎不抖，投影太短，正交失败。",-1)),a[6]||(a[6]=m("p",null,[m("span",{class:"marginnote"},'直觉类比：把投影想成影子——\\(m\\) 在收益空间上的投影是它在"可交易世界"里的影子，影子的长度就是它能撑起的最大夏普。核本身来自多古怪的偏好都行，但影子太短，就定不出观测到的价格。')],-1)),(t(),s(i,null,{default:e(()=>[o(E,{id:"mermaid-48",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E5%8F%AF%E4%BA%A4%E6%98%93%E8%B6%85%E9%A2%9D%E6%94%B6%E7%9B%8A%E5%BC%A0%E6%88%90%E7%9A%84%E7%A9%BA%E9%97%B4%22%5D%20--%3E%20P%5B%22%E5%80%99%E9%80%89%20m%20%E5%9C%A8%E8%AF%A5%E7%A9%BA%E9%97%B4%E4%B8%8A%E7%9A%84%E6%8A%95%E5%BD%B1%22%5D%0A%20%20B%5B%22%E5%81%8F%E5%A5%BD%E7%BB%99%E5%87%BA%E7%9A%84%E5%80%99%E9%80%89%20m%2C%20%E5%A6%82%20u'(c)%22%5D%20--%3E%20P%0A%20%20P%20--%3E%20T%7B%22%E6%8A%95%E5%BD%B1%E8%8C%83%E6%95%B0%20%EF%BC%9E%3D%20%E6%9C%80%E5%A4%A7%E5%A4%8F%E6%99%AE%3F%22%7D%0A%20%20T%20--%20%22%E5%A4%9F%E9%95%BF%22%20--%3E%20OK%5B%22%E5%8F%AF%E8%83%BD%E5%90%88%E6%A0%BC%2C%20%E8%BF%9B%E5%85%A5%E4%B8%8B%E4%B8%80%E5%B1%82%E6%A3%80%E9%AA%8C%22%5D%0A%20%20T%20--%20%22%E5%A4%AA%E7%9F%AD%22%20--%3E%20FAIL%5B%22%E6%AD%A3%E4%BA%A4%E5%A4%B1%E8%B4%A5%2C%20%E5%80%99%E9%80%89%20m%20%E8%A2%AB%E5%90%A6%E5%86%B3%22%5D%0A%20%20FAIL%20--%3E%20FIX%5B%22%E6%8D%A2%E6%9B%B4%E6%8A%96%E7%9A%84%E6%A0%B8%2C%20%E8%80%8C%E4%B8%8D%E6%98%AF%E5%AE%A3%E5%B8%83%E5%B8%82%E5%9C%BA%E6%97%A0%E6%95%88%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p>不完全市场时 \\(m\\) 不唯一，界约束的是集合里<strong>波动最小</strong>的那个：若连最平滑的可行 \\(m\\) 都不够抖，整个集合失败。这比指定唯一 \\(m\\) 更弱，也因此更硬——躲不进「换一个等价核」。</p><h3 id="界是会计-不是校准" tabindex="-1">界是会计，不是校准 <a class="header-anchor" href="#界是会计-不是校准" aria-label="Permalink to &quot;界是会计，不是校准&quot;">​</a></h3><p>把 HJ 界当成「估计风险厌恶」是倒过来：界不产出 \\(\\gamma\\)，它只否决太平滑的核。消费数据进入下一课，才会把 \\(\\sigma(m)\\) 翻译成 \\(\\gamma\\) 与消费增长波动的乘积。本课禁止用股权溢价的百分数改写不等式。横截面因子是否张成投影，见 <a href="/quant/ff3">/quant/ff3</a>；这里只保留可行域。</p><p><span class="marginnote">\\(m\\) 必须为正才排除套利。HJ 的波动界可以先不管正性，再加 \\(m\\gt 0\\) 的收紧。收紧后下界更高：同样的夏普要求更抖的正核。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把界的违反写成市场无效：可以是候选 \\(m\\) 错了，价格仍满足某个更抖的核。也不要把最大夏普当成无成本可交易——卖空限制、交易成本会降低可行夏普，从而放松对 \\(\\sigma(m)\\) 的要求。本课用无摩擦可交易集当基准。</p><p><span class="marginnote">常见误区：初学者容易把&quot;违反 HJ 界&quot;读成&quot;市场里有免费午餐&quot;。实际上界否决的只是你带来的那把尺子——候选核。市场可能完全正常，只是你得换一个足够抖的 \\(m\\) 才能给它定价。</span></p><p>下一课 <a href="/econ/equity-premium-puzzle">股权溢价之谜</a> 把消费欧拉放进这道界：观测到的 \\(\\sigma(\\Delta c)\\) 太小，CRRA 要极大的 \\(\\gamma\\) 才能让 \\(\\sigma(m)\\) 够格。本课不提前做 Mehra–Prescott 的校准表。</p><p>后课默认：\\(\\sigma(m)/\\mathrm{E}[m]\\) 不低于最大夏普。候选核必须落在 HJ 可行域上。这是对 \\(m\\) 的会计约束，不是 CAPM 检验。</p><p>几乎常数的 \\(m\\) 只能定价近零的夏普。股票债券的夏普已经排除风险中性核。</p><p>投影最短的 \\(m\\) 若仍不够抖，整个等价类一起失败。不完全市场不是避难所。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>由 \\(0=\\mathrm{E}[m R^e]\\) 与 Cauchy–Schwarz：定价核的变异系数 ≥ 最大夏普。</li><li>可行域只用收益数据，不指定 \\(u\\)。</li><li>违反界是否定该候选 \\(m\\)，不是自动否定有效。</li><li>出处：Hansen and Jagannathan, <em>JPE</em> 1991。</li></ul>',13))])}const F=A(p,[["render",B]]);export{C as __pageData,F as default};
